from django.db import migrations, models


def stamp_stream_faculty(apps, schema_editor):
    """Give each existing +2 stream the faculty its classes already sit under.

    Only when every class on the stream agrees on ONE faculty. A stream no class
    uses yet, or one used under two faculties, stays blank — the school picks
    the faculty in Course setup; guessing would file it under the wrong one.
    """
    Course = apps.get_model("main", "Course")
    ClassInfo = apps.get_model("main", "ClassInfo")
    for course in Course.objects.filter(education_level=3, faculty__isnull=True):
        faculties = set(
            ClassInfo.objects.filter(course=course, faculty__isnull=False)
            .values_list("faculty", flat=True)
            .distinct()
        )
        if len(faculties) == 1:
            course.faculty = faculties.pop()
            course.save(update_fields=["faculty"])


